from pathlib import Path
import re
root=Path('app/src/main/java/com/halo/app')
def edit(path,fn):
 p=root/path;p.write_text(fn(p.read_text(encoding='utf-8')),encoding='utf-8')
edit('ui/screens/settings/SystemCheckScreen.kt',lambda s:s.replace('pendingSpeechAction by androidx.compose.runtime.saveable.rememberSaveable','pendingSpeechAction by remember').replace('                item.detail?.takeIf','                var details by androidx.compose.runtime.saveable.rememberSaveable(item.id) { mutableStateOf(false) }\n                if (!item.detail.isNullOrBlank()) TextButton(onClick = { details = !details }) { Text(uiText(if (details) "Hide technical details" else "Technical details")) }\n                item.detail?.takeIf').replace('it.isNotBlank() }?.let { detail','it.isNotBlank() && details }?.let { detail').replace('            Surface(\n                shape = RoundedCornerShape(20.dp),','            Surface(\n                modifier = Modifier.heightIn(min = 48.dp),\n                shape = RoundedCornerShape(20.dp),').replace('onClick = onAction','onClick = { if (item.status != CheckStatus.RUNNING) onAction() },\n                enabled = item.status != CheckStatus.RUNNING').replace('import androidx.compose.foundation.layout.height','import androidx.compose.foundation.layout.heightIn\nimport androidx.compose.foundation.layout.height'))
edit('ui/screens/settings/AndroidAssistantScreen.kt',lambda s:s.replace('HaloScreenHeader("Android Assistant", "System interactor & gesture integration"','HaloScreenHeader(uiText("Android Assistant"), uiText("Choose Halo for Android assistant gestures")').replace('Text(bannerTitle,','Text(uiText(bannerTitle),').replace('Text(bannerSubtitle,','Text(uiText(bannerSubtitle),').replace('Triple("Integration Error", s.message,','Triple("Integration Error", "Could not inspect Android assistant status. Refresh and try again.",').replace('Text(if (state is AssistantIntegrationState.Active) "Assistant active" else "Set as Assistant")','Text(uiText(if (state is AssistantIntegrationState.Active) "Assistant active" else "Set as Assistant"))').replace('Text(enrollmentError','Text(enrollmentError').replace('        PhoneOperatorPanel()','        var technical by androidx.compose.runtime.saveable.rememberSaveable { mutableStateOf(false) }\n        TextButton(onClick = { technical = !technical }) { Text(uiText(if (technical) "Hide technical details" else "Technical details")) }\n        if (technical) PhoneOperatorPanel()').replace('        if (diag != null) {','        if (diag != null && technical) {').replace('Text(label,','Text(uiText(label),').replace('import androidx.compose.material3.Text\n','import androidx.compose.material3.Text\nimport androidx.compose.material3.TextButton\n').replace('                horizontalArrangement = Arrangement.spacedBy(12.dp)','                horizontalArrangement = Arrangement.spacedBy(12.dp)'))
edit('ui/screens/settings/StorageBackupScreen.kt',lambda s:s.replace('VaultStatus.NotConfigured -> "Automatic backup is off until you choose a folder"','VaultStatus.NotConfigured -> uiText("Automatic backup is off until you choose a folder")').replace('VaultStatus.AccessLost -> "Access lost · Choose the folder again"','VaultStatus.AccessLost -> uiText("Access lost · Choose the folder again")').replace('health.lastSuccessful?.let { "Last successful backup · ${formatBytes(it.sizeBytes ?: 0)}" } ?: "No successful backup yet"','health.lastSuccessful?.let { uiText("Last successful backup · %1$s", it.sizeBytes?.let(::formatBytes) ?: uiText("Size unavailable")) } ?: uiText("No successful backup yet")').replace('Text(schedule.name.lowercase().replaceFirstChar(Char::uppercase),','Text(uiText(schedule.name.lowercase().replaceFirstChar(Char::uppercase)),').replace('label = { Text(uiText("Password, if protected")) }, visualTransformation','label = { Text(uiText("Password, if protected")) }, keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(keyboardType = androidx.compose.ui.text.input.KeyboardType.Password), visualTransformation'))
edit('ui/screens/settings/AutomationSandboxScreen.kt',lambda s:s.replace('import androidx.compose.runtime.*','import androidx.compose.runtime.*\nimport androidx.compose.runtime.saveable.rememberSaveable\nimport com.halo.app.language.uiText').replace('import com.halo.app.language.uiText\n\nimport com.halo.app.language.uiText','import com.halo.app.language.uiText').replace('var target by remember {','var target by rememberSaveable {').replace('    var results by','    var busy by remember { mutableStateOf(false) }\n    var failure by remember { mutableStateOf(false) }\n    var results by').replace('HaloWorkspaceHeader("Automation sandbox", "Internal preview · no actions or delivery"','HaloWorkspaceHeader(uiText("Automation sandbox"), uiText("Internal preview · no actions or delivery")').replace('HaloWorkspaceButton(label, onClick = { scope.launch {','HaloWorkspaceButton(uiText(label), enabled = !busy, onClick = { if (!busy) { busy = true; failure = false; scope.launch { try {').replace('            } })','            } catch (cancelled: kotlinx.coroutines.CancellationException) { throw cancelled } catch (_: Exception) { failure = true } finally { busy = false } } } })').replace('        results.forEach','        if (busy) com.halo.app.ui.design.HaloProgressPresentation(uiText("Preparing preview…"))\n        if (failure) Text(uiText("Preview failed. Try again. No actions were executed."))\n        results.forEach'))
edit('ui/screens/integrations/IntegrationsScreen.kt',lambda s:s.replace('Text("${servers.size} servers · ${servers.sumOf { server -> server.tools.count { it.enabled } }} enabled tools",','Text(uiText("%1$d servers · %2$d enabled tools", servers.size, servers.sumOf { server -> server.tools.count { it.enabled } }),').replace('Text("${server.tools.size} tools · ${server.tools.count { it.enabled }} enabled",','Text(uiText("%1$d tools · %2$d enabled", server.tools.size, server.tools.count { it.enabled }),').replace('onClickLabel = "Open ${server.displayName}"','onClickLabel = uiText("Open %1$s", server.displayName)').replace('Text(when (level) {','Text(uiText(when (level) {').replace('"A server you control in your local environment." },','"A server you control in your local environment." }),'))
edit('ui/screens/integrations/McpServerScreen.kt',lambda s:s.replace('Text("Remove ${server?.displayName}?")','Text(uiText("Remove %1$s?", server?.displayName.orEmpty()))'))
for file in ['EverydayRoutineEditor','AutomationScreen']:
 edit(f'ui/screens/settings/{file}.kt',lambda s:s.replace('routine.trigger.humanLabel(', 'routine.trigger.uiLabel(').replace('condition.humanLabel(', 'condition.uiLabel(').replace('routine.delivery.humanLabel(', 'routine.delivery.uiLabel(').replace('routine.actions.joinToString("\\n") { it.humanLabel() }','routine.actions.map { it.uiLabel() }.joinToString("\\n")').replace('routine.conditions.takeIf { it.isNotEmpty() }?.joinToString("\\n") { it.humanLabel(labels) } ?: "No additional conditions"','routine.conditions.takeIf { it.isNotEmpty() }?.map { it.uiLabel(labels) }?.joinToString("\\n") ?: uiText("No additional conditions")').replace('Text(run.state.humanLabel())','Text(uiText(run.state.humanLabel()))').replace('Text(watch.status.humanLabel())','Text(uiText(watch.status.humanLabel()))').replace('humanInterval(routine.minimumIntervalSeconds)','uiInterval(routine.minimumIntervalSeconds)').replace('ListItem(headlineContent = { Text(title) }, supportingContent = subtitle?.let { { Text(it) } }','ListItem(headlineContent = { Text(uiText(title)) }, supportingContent = subtitle?.let { { Text(uiText(it)) } }'))
# App-authored literal labels throughout all reachable UI, including accessibility text.
for p in (root/'ui').rglob('*.kt'):
 s=p.read_text(encoding='utf-8');original=s
 s=re.sub(r'(?<![A-Za-z0-9_])Text\(\s*(?:text\s*=\s*)?("[^"$\\\n]+")',lambda m: m.group(0)[:m.group(0).index('"')]+'uiText('+m.group(1)+')',s)
 # Named titles and descriptions on composable calls must be localized at their owner.
 for prop in []:
  s=re.sub(r'\b'+prop+r'\s*=\s*("[^"$\\\n]+")',prop+r' = uiText(\1)',s)
 if s!=original:
  if 'import com.halo.app.language.uiText' not in s:s=s.replace('\n\n','\n\nimport com.halo.app.language.uiText\n',1)
  p.write_text(s,encoding='utf-8')
